:root {
  /* Colors */
  --color-linen-canvas: #f0f0ec;
  --color-paper-surface: #f8f8f8;
  --color-frosted-card: #fdfdfe;
  --color-forest-ink: #192319;
  --color-moss-ink: #3c483c;
  --color-ink-caption: #192319a3;
  --color-fog-text: #dcdcd7;
  --color-stone-border: #c8c8be;
  --color-ink-ring: #0a140a1f;
  --color-keylime-signal: #abe082;
  --color-sky-pulse: #4790dd;
  --color-sunbeam-pulse: #f1be23;
  --color-ember-pulse: #f55524;

  /* Typography — Font Families */
  --font-p22-mackinac-pro: "P22 Mackinac Pro", "Newsreader", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-atkinson-hyperlegible-next: "Atkinson Hyperlegible Next", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-atkinson-hyperlegible-mono: "Atkinson Hyperlegible Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12.5px;
  --leading-small: 1.6;
  --tracking-small: 0.25px;
  --text-caption: 14px;
  --leading-caption: 1.4;
  --tracking-caption: 0px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.4;
  --tracking-body-sm: 0.27px;
  --text-body: 16.5px;
  --leading-body: 1.4;
  --tracking-body: 0.27px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: 0.3px;
  --text-subheading: 24px;
  --leading-subheading: 1.1;
  --tracking-subheading: -0.48px;
  --text-heading-sm: 36px;
  --leading-heading-sm: 1.1;
  --tracking-heading-sm: -1.44px;
  --text-heading: 50px;
  --leading-heading: 0.95;
  --tracking-heading: -2px;
  --text-heading-lg: 70px;
  --leading-heading-lg: 0.95;
  --tracking-heading-lg: -2.8px;
  --text-display: 92px;
  --leading-display: 0.95;
  --tracking-display: -6.44px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-26: 26px;
  --spacing-30: 30px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-44: 44px;
  --spacing-60: 60px;
  --spacing-80: 80px;
  --spacing-100: 100px;
  --spacing-120: 120px;
  --spacing-200: 200px;

  /* Layout */
  --layout-page-max-width: 1360px;
  --layout-section-gap: 100px;
  --layout-card-padding: 60px;
  --layout-element-gap: 20px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 13px;
  --radius-xl: 24px;
  --radius-2xl: 32px;
  --radius-3xl: 40px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 32px;
  --radius-images: 24px;
  --radius-small-cards: 13px;
  --radius-small-elements: 8px;
  --radius-tags: 4px;
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-nav: 9999px;
  --radius-avatars: 50%;
  --radius-sections: 0px 0px 40px 40px;

  /* Shadows */
  --shadow-subtle: 0px 8px 40px 0px rgba(0, 0, 0, 0.1);
  --shadow-sm: 0px 2px 44px 0px rgba(0, 0, 0, 0.14);
  --shadow-md: 0px 8px 36px 0px rgba(0, 0, 0, 0.18);
  --shadow-md-2: 0px 7.34px 33px 0px rgba(0, 0, 0, 0.18);
  --shadow-lg: 0px 4px 4px 0px rgba(0, 0, 0, 0.1), 0px 8px 40px 0px rgba(0, 0, 0, 0.1);

  /* Surfaces */
  --surface-linen-canvas: #f0f0ec;
  --surface-paper-surface: #f8f8f8;
  --surface-frosted-card: #fdfdfe;
  --surface-forest-ink: #192319;
}

